local R = require "core.lib.rathena"

return function(player, conversation, npc, ...)
  local type_ = 0
  local args = table.pack(...)
  type_ = (R.arg(args, 0) or 0)
  conversation:say("[Kafra Employee]")
  if (R.arg(args, 1) == 1) then
    conversation:say("Your Respawn Point", "has been saved here", "" .. R.arg(args, 2) .. ".", "Thank you for using", "the Kafra Services.")
  elseif ((type_ == 0) or (type_ == 5)) then
    conversation:say("We, here at Kafra Corporation,", "are always endeavoring to provide you with the best services. We hope that we meet your adventuring needs and standards of excellence.")
  elseif (type_ == 1) then
    R.unsupported("percentheal")
    conversation:say("^666666Kaffffra n-never", "diiiiiiiiiiiiiies. On...", "On y-yooour siiiiide~^000000")
  elseif (type_ == 2) then
    conversation:say("Saved.", "Thank you for your patronage.")
  end
  conversation:hide_image()
  R.stop()
end
